package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AResultRepository implements A2AResultRepository {
 private final A2AResultDao dao; private final A2APersistenceConverter c; public MybatisA2AResultRepository(A2AResultDao d,A2APersistenceConverter c){dao=d;this.c=c;}
 public A2AResult save(A2AResult v){int inserted=dao.insert(c.toPo(v));A2AResult canonical=findByRequest(v.getTenantId(),v.getRequestId()).orElseThrow();if(inserted==0&&!same(canonical,v))throw new IllegalStateException("A2A_CANONICAL_RESULT_CONFLICT");return canonical;}
 public Optional<A2AResult> findById(String t,String id){return Optional.ofNullable(dao.findById(t,id)).map(c::toDomain);} public Optional<A2AResult> findByRequest(String t,String id){return Optional.ofNullable(dao.findByRequest(t,id)).map(c::toDomain);} public Optional<A2AResult> findByIdempotencyKey(String t,String k){return k==null?Optional.empty():Optional.ofNullable(dao.findByIdempotencyKey(t,k)).map(c::toDomain);} public List<A2AResult> findByParentTask(String t,String id,int n){return dao.findByParentTask(t,id,Math.max(1,Math.min(n,1000))).stream().map(c::toDomain).toList();} public String mode(){return "MYBATIS";}
 private boolean same(A2AResult a,A2AResult b){return Objects.equals(a.getResultFingerprint(),b.getResultFingerprint())&&a.getResultStatus()==b.getResultStatus()&&Objects.equals(a.getResultEvidenceHash(),b.getResultEvidenceHash())&&a.getPolicyVersion()==b.getPolicyVersion()&&Objects.equals(a.getPolicySnapshotHash(),b.getPolicySnapshotHash());}
}
